#include <complex>

// Quad-precision types (GCC extension, matches QCDLoop qdouble/qcomplex).
// These are only usable when compiled with GCC; see original Fortran comment.
typedef __float128    ql_qdouble;
typedef __complex128  ql_qcomplex;

input.new_string:
#include <complex>

// Quad-precision types (GCC extension, matches QCDLoop qdouble/qcomplex).
// Requires quadmath.h for __float128/__complex128; matches QCDLoop's own types.h.
// These are only usable when compiled with GCC; see original Fortran comment.
#ifdef __SIZEOF_FLOAT128__
extern "C" {
#include <quadmath.h>
}
typedef __float128    ql_qdouble;
typedef __complex128  ql_qcomplex;
#endif

input.old_string:
// Quad-precision variants (GCC/gfortran only; no standard C binding for real128).
ql_qcomplex qli1q(ql_qdouble const& m1, ql_qdouble const& mu2, int const& ep);
ql_qcomplex qli2q(ql_qdouble const& p1, ql_qdouble const& m1, ql_qdouble const& m2,
                  ql_qdouble const& mu2, int const& ep);
ql_qcomplex qli3q(ql_qdouble const& p1, ql_qdouble const& p2, ql_qdouble const& p3,
                  ql_qdouble const& m1, ql_qdouble const& m2, ql_qdouble const& m3,
                  ql_qdouble const& mu2, int const& ep);
ql_qcomplex qli4q(ql_qdouble const& p1, ql_qdouble const& p2, ql_qdouble const& p3, ql_qdouble const& p4,
                  ql_qdouble const& s12, ql_qdouble const& s23,
                  ql_qdouble const& m1, ql_qdouble const& m2, ql_qdouble const& m3, ql_qdouble const& m4,
                  ql_qdouble const& mu2, int const& ep);

ql_qcomplex qli1qc(ql_qcomplex const& m1, ql_qdouble const& mu2, int const& ep);
ql_qcomplex qli2qc(ql_qdouble const& p1, ql_qcomplex const& m1, ql_qcomplex const& m2,
                   ql_qdouble const& mu2, int const& ep);
ql_qcomplex qli3qc(ql_qdouble const& p1, ql_qdouble const& p2, ql_qdouble const& p3,
                   ql_qcomplex const& m1, ql_qcomplex const& m2, ql_qcomplex const& m3,
                   ql_qdouble const& mu2, int const& ep);
ql_qcomplex qli4qc(ql_qdouble const& p1, ql_qdouble const& p2, ql_qdouble const& p3, ql_qdouble const& p4,
                   ql_qdouble const& s12, ql_qdouble const& s23,
                   ql_qcomplex const& m1, ql_qcomplex const& m2, ql_qcomplex const& m3, ql_qcomplex const& m4,
                   ql_qdouble const& mu2, int const& ep);

